      "pinyin": "小时不识月，呼作白玉盘。\n又疑瑶{yáo}台镜，飞在青云端。\n仙人垂两足，桂树何团团。\n白兔捣药成，问言与谁餐？\n蟾{chán}蜍{chú}蚀{shí}圆影，大明夜已残。\n羿{yì}昔落九乌，天人清且安。\n阴精此沦惑，去去不足观。\n忧来其如何？凄怆{chuàng}摧心肝。",
      "translation": "小时候不认识月亮，把它叫作白玉盘。又怀疑它是瑶台上的仙镜，飞在青云之上。仙人垂着两只脚，桂树长得多么圆团团。白兔把药捣成了，请问要送给谁吃？蟾蜍啃食了圆月，月亮因此暗淡残缺。后羿当年射落九个太阳，天上人间才清朗安宁。如今月亮沉沦昏惑，走吧走吧不值得再看。忧愁袭来该怎么办？凄惨悲伤摧人心肝。",
