      "tag": "春天",
      "pinyin": "草长莺{yīng}飞二月天，拂{fú}堤{dī}杨柳醉春烟。\n儿童散学归来早，忙趁东风放纸鸢{yuān}。",
      "translation": "农历二月，青草生长，黄莺飞舞，轻拂堤岸的杨柳陶醉在春天的烟雾里。孩子们放学回来得早，赶忙趁着东风放起了风筝。",
      "analysis": "前两句写景，描绘早春二月明媚的田园风光；后两句写人，孩子们放风筝的欢快场景。景中有人，人中有景，充满生活情趣。",
