      "pinyin": "碧玉妆{zhuāng}成一树高，万条垂下绿丝绦{tāo}。\n不知细叶谁裁{cái}出，二月春风似剪刀。",
      "translation": "高高的柳树像是用碧玉装扮而成，千万条柳枝垂下来，像绿色的丝带。不知道这细细的柳叶是谁裁剪出来的？原来二月的春风就像一把剪刀。",
      "analysis": "全诗咏柳，前两句用「碧玉」「丝绦」两个比喻写柳树的绿和柔；后两句设问，把春风比作剪刀，想象新奇，既写出柳叶的细巧，又赞美了春天的创造力。",
