      "tag": "夏天",
      "pinyin": "毕竟西湖六月中，风光不与四时同。\n接天莲叶无穷碧，映日荷花别样红。",
      "translation": "到底是六月的西湖，风光和其他季节大不相同。那连天的莲叶一片无穷的碧绿，映着阳光的荷花显得格外红艳。",
      "analysis": "前两句总写六月西湖风光之独特；后两句用「无穷碧」写莲叶之广，用「别样红」写荷花之艳，色彩对比鲜明，画面壮阔，是描写西湖荷花的千古名篇。",
