      "title": "出塞",
      "dynasty": "唐",
      "author": "王昌龄",
      "level": "primary",
      "grade": "四年级上",
      "tag": "边塞",
      "pinyin": "秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教{jiào}胡马度阴山。",
      "translation": "依旧是秦汉时的明月和边关，万里出征的将士却还没有回来。只要有像李广那样的飞将军在，就不会让敌人的战马越过阴山。",
      "analysis": "首句用「秦时明月汉时关」的互文手法，写出边塞历史的悠久；后两句借怀念名将，表达对良将的渴望和对和平的向往。被誉为唐人七绝的压卷之作。",
      "points": [
        "「但使」意为只要",
        "「不教」意为不让，读 jiào",
        "互文：秦汉明月、秦汉边关"
      ]
