      "grade": "五年级上",
      "tag": "山水",
      "pinyin": "空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣{huàn}女，莲动下渔舟。\n随意春芳歇{xiē}，王孙自可留。",
      "translation": "空旷的山中刚下过一场新雨，傍晚的天气更显秋意。明月照在松林间，清泉在山石上流淌。竹林喧响，是洗衣女子归来；莲叶摇动，是渔船顺流而下。任凭春天的芳菲消歇，我自可以留在这山中。",
      "analysis": "这是王维山水诗的代表作。诗中明月、清泉、浣女、渔舟，构成一幅清幽恬静的山居秋夜图。尾联化用典故，表达诗人归隐山林的志趣。",
