      "translation": "月亮落下，乌鸦啼叫，寒霜弥漫满天；江边的枫树和渔船的灯火，陪伴着满怀愁绪难以入眠的我。姑苏城外的寒山寺，半夜里敲响的钟声传到了客船上。",
