      "pinyin": "山一程，水一程，身向榆{yú}关那畔行，夜深千帐灯。\n风一更{gēng}，雪一更，聒{guō}碎乡心梦不成，故园无此声。",
      "translation": "翻过一座座山，涉过一条条河，向着榆关那边行进，夜深了，千万个帐篷里都亮着灯。风刮了一更又一更，雪下了一更又一更，嘈杂的声音吵碎了思乡的心，连梦都做不成，故乡可没有这样的声音啊。",
      "analysis": "上阕写行军途中的遥远和夜晚营帐的壮观；下阕写风雪交加、乡愁难眠。全词以「山一程，水一程」「风一更，雪一更」的反复，写出征途的漫长和思乡的深切。",
