      "pinyin": "青海长云暗雪山，孤城遥望玉门关。\n黄沙百战穿金甲，不破楼兰终不还。",
      "translation": "青海湖上长云弥漫，雪山暗淡无光；一座孤城遥遥望着玉门关。在黄沙中身经百战，磨穿了铠甲；不打败敌人，誓不归还。",
