      "grade": "五年级下",
      "tag": "爱国",
      "pinyin": "剑外忽传收蓟{jì}北，初闻涕{tì}泪满衣裳。\n却看妻子愁何在，漫卷诗书喜欲狂。\n白日放歌须纵酒，青春作伴好还乡。\n即从巴峡穿巫峡，便下襄阳向洛阳。",
      "translation": "剑门关外忽然传来收复蓟北的消息，我刚一听到就泪流满面。回头看妻子儿女，哪里还有愁容？我胡乱地卷起诗书，高兴得几乎发狂。白天要放声高歌、纵情饮酒，趁着明媚春光与妻儿一同返回故乡。就从巴峡穿过巫峡，再下襄阳直奔洛阳。",
      "analysis": "这是杜甫生平第一首快诗。全诗围绕一个「喜」字，从初闻惊喜、喜极而泣，到卷书欲狂、放歌纵酒，再到归心似箭，层层推进，把收复失地的狂喜写得淋漓尽致。",
