      "grade": "六年级下",
      "tag": "古诗",
      "pinyin": "迢{tiáo}迢牵牛星，皎{jiǎo}皎河汉女。\n纤纤擢{zhuó}素手，札{zhá}札弄机杼{zhù}。\n终日不成章，泣涕零如雨。\n河汉清且浅，相去复几许？\n盈盈一水间，脉{mò}脉不得语。",
      "translation": "遥远的牵牛星，明亮的织女星。织女伸出纤细洁白的手，札札地摆弄着织布机。一整天也织不成一匹布，眼泪像雨一样落下。银河又清又浅，相隔又能有多远？只隔着一条清澈的银河，却只能含情相视，不能说话。",
      "analysis": "这首诗借牛郎织女的传说，写相思之苦。全诗多用叠词（迢迢、皎皎、纤纤、札札、盈盈、脉脉），音韵和谐，把织女的哀怨写得缠绵动人。",
