      "pinyin": "中庭地白树栖{qī}鸦，冷露无声湿桂花。\n今夜月明人尽望，不知秋思落谁家？",
      "translation": "庭院中月光如霜，地面一片洁白，树上栖息着乌鸦；清冷的露水悄无声息地打湿了桂花。今夜明月当空，人们都在仰望，不知道这秋天的情思会落在谁家？",
