      "pinyin": "萧萧梧叶送寒声，江上秋风动客情。\n知有儿童挑{tiǎo}促{cù}织，夜深篱落一灯明。",
      "translation": "萧瑟的秋风吹动梧桐叶，送来阵阵寒意；江上的秋风勾起了游子的思乡之情。料想是孩子们在捉蟋蟀，因为夜深了，篱笆下还有一盏灯亮着。",
      "analysis": "前两句写秋风落叶，以「寒声」「客情」点出羁旅之愁；后两句笔锋一转，由「一灯明」推测儿童夜捉蟋蟀，画面顿时温暖起来。以乐景写哀情，更显思乡之切。",
