      "translation": "牧童骑在黄牛背上，嘹亮的歌声在树林中回荡。他忽然想要捕捉树上鸣叫的蝉，于是马上闭住嘴，一声不响地站立在树旁。",
      "analysis": "全诗只二十字，却写出牧童由「动」到「静」的瞬间变化：前两句写骑牛高歌的欢快，后两句写欲捕鸣蝉的专注。一「振」一「闭」，动静对比，童趣盎然。",
