      "pinyin": "荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。",
      "translation": "采莲女的罗裙和荷叶仿佛是用同一种颜色裁剪出来的，荷花朝着她的脸庞两边盛开。她混入莲池中，就再也看不见了；听到歌声，才知道有人来了。",
      "analysis": "诗人不直接写采莲女的美，而是把她融入荷叶荷花之中：裙与叶同色，脸与花相映。末句「闻歌始觉有人来」以声写人，含蓄巧妙，是描写采莲的绝唱。",
