      "pinyin": "人间四月芳菲{fēi}尽，山寺桃花始盛开。\n长恨春归无觅{mì}处，不知转入此中来。",
      "translation": "人世间的四月，百花已经凋谢；山寺里的桃花才刚刚盛开。我常常遗憾春天归去后无处寻找，却不知道它转到了这山寺之中。",
