      "pinyin": "云母屏风烛影深，长河渐落晓星沉。\n嫦娥应悔偷灵药，碧海青天夜夜心。",
      "translation": "云母屏风上烛影渐渐暗淡，银河慢慢西沉，晨星也消失了。嫦娥应该后悔偷吃了灵药吧，如今只能对着碧海青天，夜夜孤寂。",
