      "pinyin": "红军不怕远征难，万水千山只等闲。\n五岭逶{wēi}迤{yí}腾细浪，乌蒙磅{páng}礴{bó}走泥丸。\n金沙水拍云崖暖，大渡桥横铁索寒。\n更喜岷{mín}山千里雪，三军过后尽开颜。",
