      "pinyin": "东临碣{jié}石，以观沧海。\n水何澹澹{dàn}，山岛竦{sǒng}峙{zhì}。\n树木丛生，百草丰茂。\n秋风萧瑟，洪波涌起。\n日月之行，若出其中；\n星汉灿烂，若出其里。\n幸甚至哉，歌以咏志。",
