      "tag": "闲适",
      "pinyin": "黄梅时节家家雨，青草池塘处处蛙。\n有约不来过夜半，闲敲棋子落灯花。",
      "translation": "梅雨时节，家家户户都笼罩在雨中；长满青草的池塘里，处处是青蛙的鸣叫。约好的客人过了半夜还没有来，我无聊地敲着棋子，震落了灯花。",
      "analysis": "前两句写江南梅雨季节的景色，以「家家雨」「处处蛙」写出环境的清幽；后两句写候客不至的闲适与淡淡的怅惘，「闲敲棋子落灯花」细节传神。",
