      "tag": "隐逸",
      "pinyin": "独坐幽篁{huáng}里，弹琴复长啸。\n深林人不知，明月来相照。",
      "translation": "独自坐在幽深的竹林里，一边弹琴一边长啸。深林中没有人知道，只有明月来相照。",
      "analysis": "全诗写诗人独坐竹林、弹琴长啸的闲适生活。以「幽篁」「深林」「明月」营造清幽意境，表现出诗人远离尘嚣、恬淡自适的心境。",
