      "tag": "思乡",
      "pinyin": "谁家玉笛暗飞声，散入春风满洛城。\n此夜曲中闻折柳，何人不起故园情。",
      "translation": "不知从谁家飞出悠扬的玉笛声，随着春风飘散，传遍了洛阳城。今夜听到《折杨柳》的曲子，有谁能不勾起思念故乡的感情呢？",
      "analysis": "前两句写笛声随春风传遍全城，「暗飞声」「满洛城」写出笛声的悠扬和传播之广；后两句因《折杨柳》的曲调引发思乡之情，以反问作结，余韵悠长。",
