      "tag": "思乡",
      "pinyin": "故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。",
      "translation": "向东遥望故乡，路途遥远漫长；双袖都被泪水沾湿了，泪水还流个不停。在马上与你相遇，没有纸笔写信，只好请你捎个口信，告诉我家人我平安。",
      "analysis": "前两句写思乡之切，「龙钟」形容泪水淋漓；后两句写途中偶遇入京使者，因无纸笔只能捎口信报平安。语言质朴，情感真挚，生活气息浓厚。",
