      "tag": "春天",
      "pinyin": "草树知春不久归，百般红紫斗芳菲{fēi}。\n杨花榆荚{jiá}无才思，惟解漫天作雪飞。",
      "translation": "花草树木知道春天不久就要归去，于是万紫千红，争芳斗艳。只有那杨花和榆荚没有才思，只知道像雪花一样漫天飞舞。",
      "analysis": "诗人用拟人手法写晚春：草木「知春不久归」，所以「斗芳菲」；杨花榆荚「无才思」，只能「作雪飞」。在惜春之中，也暗含对平凡事物也能有所作为的肯定。",
