      "grade": "八年级下",
      "tag": "干谒",
      "pinyin": "八月湖水平，涵虚混太清。\n气蒸云梦泽，波撼岳阳城。\n欲济无舟楫{jí}，端居耻圣明。\n坐观垂钓者，徒有羡鱼情。",
      "translation": "八月洞庭湖的水面与岸齐平，水天相连，浑然一体。水汽蒸腾，笼罩着云梦泽；波涛汹涌，震撼着岳阳城。想渡湖却没有船只，闲居在家又愧对圣明的时代。只能坐着看别人垂钓，空有羡慕鱼儿上钩的心情。",
