      "level": "middle",
      "grade": "八年级上",
      "tag": "怀古",
      "pinyin": "折戟{jǐ}沉沙铁未销{xiāo}，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。",
