      "tag": "怀古",
      "pinyin": "何处望神州？满眼风光北固楼。\n千古兴亡多少事？悠悠。不尽长江滚滚流。\n年少万兜{dōu}鍪{móu}，坐断东南战未休。\n天下英雄谁敌手？曹刘。生子当如孙仲谋。",
