      "grade": "九年级下",
      "tag": "言志",
      "pinyin": "小住京华，早又是中秋佳节。\n为篱下黄花开遍，秋容如拭{shì}。\n四面歌残终破楚，八年风味徒思浙。\n苦将侬{nóng}强派作蛾眉，殊未屑！\n身不得，男儿列；心却比，男儿烈。\n算平生肝胆，因人常热。\n俗子胸襟谁识我？英雄末路当磨折。\n莽{mǎng}红尘何处觅知音？青衫湿！",
      "translation": "我暂住北京，转眼又到了中秋佳节。篱笆下开遍了黄色的菊花，秋景明净得像擦拭过一样。四面楚歌，终于冲破牢笼；八年来徒然思念浙江故乡。苦苦地把我勉强当作女子，我实在不屑！我身子不能列入男子行列，心却比男子还要刚烈。想想平生的赤胆忠心，常常因他人而热血沸腾。世俗之人谁能理解我？英雄末路，本应经受磨难。茫茫红尘中到哪里去寻找知音？泪水沾湿了衣裳。",
      "analysis": "这是秋瑾的词作。上阕写中秋时节客居京华，抒发对身为女子的不甘；下阕直抒胸臆，表达虽为女子却有胜于男子的豪情，以及不被世俗理解的孤独。全词慷慨激昂，充满革命豪情。",
