      "id": "p120",
      "title": "行路难（其一）",
      "dynasty": "唐",
      "author": "李白",
      "level": "middle",
      "grade": "九年级上",
      "tag": "言志",
      "pinyin": "金樽{zūn}清酒斗十千，玉盘珍羞直万钱。\n停杯投箸{zhù}不能食，拔剑四顾心茫然。\n欲渡黄河冰塞川，将登太行雪满山。\n闲来垂钓碧溪上，忽复乘舟梦日边。\n行路难，行路难，多歧路，今安在？\n长风破浪会有时，直挂云帆济沧海。",
      "translation": "金杯中的清酒一斗值十千钱，玉盘里的珍馐美味价值万钱。我停下酒杯，扔掉筷子，吃不下饭，拔剑四顾，心中一片茫然。想渡过黄河，冰却塞住了河道；想登上太行山，大雪却封住了山路。闲来在碧溪上垂钓，忽然又梦见乘船经过太阳旁边。行路难啊，行路难，道路分歧众多，我如今身在何处？总有一天能乘长风破万里浪，直挂云帆，横渡沧海。",
      "analysis": "前四句写诗人面对美酒佳肴却无心下咽，表现内心的苦闷抑郁；中间写「冰塞川」「雪满山」象征仕途受阻；接着以姜尚、伊尹的典故表达对未来的希望；最后以「长风破浪会有时，直挂云帆济沧海」的豪迈之语收束，表现了诗人积极乐观、执着追求的品格。",
      "points": [
        "「樽」读 zūn，酒杯",
        "「箸」读 zhù，筷子",
        "「羞」通「馐」，美味的食物",
        "「济」意为渡过",
        "名句：长风破浪会有时，直挂云帆济沧海"
      ]
