      "dynasty": "宋",
      "author": "苏轼",
      "level": "middle",
      "grade": "九年级下",
      "tag": "词",
      "pinyin": "老夫聊发少年狂，左牵黄，右擎{qíng}苍，\n锦帽貂{diāo}裘{qiú}，千骑{jì}卷平冈。\n为报倾城随太守，亲射虎，看孙郎。\n酒酣胸胆尚开张，鬓微霜，又何妨！\n持节云中，何日遣冯唐？\n会挽雕弓如满月，西北望，射天狼。",
      "translation": "老夫姑且发一发少年的狂放，左手牵着黄犬，右臂托着苍鹰；头戴锦帽，身穿貂裘，千骑奔驰，席卷平冈。为了报答全城百姓跟随太守出猎的盛意，我要亲自射杀老虎，让大家看看孙权的英姿。酒喝得畅快，胸怀胆气更加豪壮，鬓角微白，又有什么关系！什么时候朝廷能像派冯唐赦免魏尚那样起用我呢？到那时，我一定拉满雕弓，像满月一样，朝着西北方向，射向天狼星。",
      "analysis": "这首词写密州出猎的壮观场面，表达了诗人渴望报效国家、建功立业的豪情。上阕写出猎，气势恢宏；下阕写请战，以「会挽雕弓如满月，西北望，射天狼」的豪迈之语收束，慷慨激昂。",
