      "tag": "词",
      "pinyin": "三月七日，沙湖道中遇雨，雨具先去，同行皆狼狈，余独不觉。已而遂晴，故作此词。\n莫听穿林打叶声，何妨吟啸且徐行。\n竹杖芒鞋轻胜马，谁怕？一蓑{suō}烟雨任平生。\n料峭{qiào}春风吹酒醒，微冷，山头斜照却相迎。\n回首向来萧瑟处，归去，也无风雨也无晴。",
      "translation": "三月七日，在沙湖道上遇到下雨，拿雨具的人先走了，同行的人都很狼狈，只有我不觉得。不久天晴了，于是写下这首词。不要听那穿林打叶的雨声，不妨一边吟诗长啸一边慢慢前行。竹杖草鞋，比骑马还要轻便，怕什么？披一件蓑衣，任凭一生烟雨。料峭的春风吹醒了酒意，微微感到寒冷，山头的斜阳却来相迎。回头看看刚才风雨萧瑟的地方，回去时，既没有风雨也没有晴天。",
      "analysis": "这首词写途中遇雨的小事，却表现了诗人旷达乐观的人生态度。「一蓑烟雨任平生」写出面对人生风雨的从容；结尾「也无风雨也无晴」更是超然物外，达到物我两忘的境界。",
