      "pinyin": "相见时难别亦难，东风无力百花残。\n春蚕到死丝方尽，蜡炬{jù}成灰泪始干。\n晓镜但愁云鬓{bìn}改，夜吟应觉月光寒。\n蓬山此去无多路，青鸟殷勤为探看。",
      "translation": "相见本来就难，离别更是难舍难分；东风无力，百花凋残。春蚕到死才把丝吐尽，蜡烛烧成灰烬泪水才干。清晨对镜梳妆，只愁鬓发变白；夜里吟诗，应该感到月光寒冷。蓬莱仙山离这里没有多远，青鸟啊，请你殷勤地为我探看。",
