      "tag": "怀古",
      "pinyin": "一上高城万里愁，蒹{jiān}葭{jiā}杨柳似汀{tīng}洲。\n溪云初起日沉阁，山雨欲来风满楼。\n鸟下绿芜{wú}秦苑夕，蝉鸣黄叶汉宫秋。\n行人莫问当年事，故国东来渭水流。",
