      "pinyin": "树绕村庄，水满陂{bēi}塘。倚东风，豪兴徜{cháng}徉{yáng}。\n小园几许，收尽春光。有桃花红，李花白，菜花黄。\n远远围墙，隐隐茅堂。飏{yáng}青旗，流水桥旁。\n偶然乘兴，步过东冈。正莺儿啼，燕儿舞，蝶儿忙。",
      "translation": "绿树环绕着村庄，春水溢满了池塘。我趁着春风，兴致勃勃地漫步。小园虽然不大，却收尽了春光：有红色的桃花，白色的李花，黄色的菜花。远远的围墙，隐隐的茅草屋。青色的酒旗飘扬，小桥流水旁。偶然乘着兴致，走过东边的山冈。正是黄莺啼叫、燕子飞舞、蝴蝶忙碌的时候。",
