      "pinyin": "昔人已乘黄鹤去，此地空余黄鹤楼。\n黄鹤一去不复返，白云千载空悠悠。\n晴川历历汉阳树，芳草萋萋{qī}鹦{yīng}鹉{wǔ}洲。\n日暮乡关何处是？烟波江上使人愁。",
