      "tag": "古诗",
      "pinyin": "庭中有奇树，绿叶发华滋。\n攀条折其荣，将以遗{wèi}所思。\n馨{xīn}香盈怀袖，路远莫致之。\n此物何足贵，但感别经时。",
      "translation": "庭院中有一棵美好的树，绿叶间开满了繁盛的花。我攀着枝条折下一朵花，想要送给我思念的人。花香充满了衣袖，可是路途遥远，无法送到。这花有什么珍贵呢？只是感慨离别已经太久罢了。",
