      "pinyin": "关关雎{jū}鸠{jiū}，在河之洲。窈{yǎo}窕{tiǎo}淑女，君子好逑{qiú}。\n参差荇{xìng}菜，左右流之。窈窕淑女，寤{wù}寐{mèi}求之。\n求之不得，寤寐思服。悠哉悠哉，辗转反侧。\n参差荇菜，左右采之。窈窕淑女，琴瑟友之。\n参差荇菜，左右芼{mào}之。窈窕淑女，钟鼓乐之。",
      "translation": "雎鸠鸟关关地鸣叫，在河中的小洲上。美丽善良的姑娘，是君子的好配偶。长短不齐的荇菜，左右不停地采摘。美丽善良的姑娘，我日夜思念追求她。追求不到，日夜思念。思念绵绵不断，翻来覆去睡不着。长短不齐的荇菜，左右不停地采摘。美丽善良的姑娘，我弹琴鼓瑟来亲近她。长短不齐的荇菜，左右不停地挑选。美丽善良的姑娘，我敲钟击鼓使她快乐。",
      "analysis": "《关雎》是《诗经》的首篇。全诗以雎鸠起兴，写君子对淑女的思慕与追求。诗中「寤寐求之」「辗转反侧」写思念之苦，「琴瑟友之」「钟鼓乐之」写追求之诚。运用重章叠句，反复咏唱，情感真挚健康。",
