      "pinyin": "蒹{jiān}葭{jiā}苍苍，白露为霜。所谓伊人，在水一方。\n溯{sù}洄{huí}从之，道阻且长。溯游从之，宛在水中央。\n蒹葭萋萋，白露未晞{xī}。所谓伊人，在水之湄{méi}。\n溯洄从之，道阻且跻{jī}。溯游从之，宛在水中坻{chí}。\n蒹葭采采，白露未已。所谓伊人，在水之涘{sì}。\n溯洄从之，道阻且右。溯游从之，宛在水中沚{zhǐ}。",
      "translation": "芦苇苍苍茫茫，白露凝结成霜。我所思念的那个人，在河水的另一边。逆流而上去追寻她，道路险阻又漫长。顺流而下去追寻她，她仿佛就在水的中央。芦苇茂盛繁密，白露还没有干。我所思念的那个人，在河岸边。逆流而上去追寻她，道路险阻又高陡。顺流而下去追寻她，她仿佛就在水中的小洲上。芦苇丛生茂密，白露还没有消失。我所思念的那个人，在水边。逆流而上去追寻她，道路险阻又曲折。顺流而下去追寻她，她仿佛就在水中的沙洲上。",
      "analysis": "全诗三章，以蒹葭、白露起兴，反复咏叹对「伊人」的追寻。伊人可望而不可即，营造出一种迷离恍惚、朦胧悠远的意境。重章叠句的运用，使情感层层递进，是《诗经》中意境最美的篇章之一。",
      "points": [
        "「蒹葭」读 jiān jiā，芦苇",
        "「溯洄」读 sù huí，逆流而上",
        "「晞」读 xī，意为晒干",
        "「湄」读 méi，水边",
        "「跻」读 jī，意为升高",
        "「坻」读 chí，水中小洲",
        "「涘」读 sì，水边",
        "「沚」读 zhǐ，水中小块陆地"
      ]
