      "grade": "八年级下",
      "tag": "爱情",
      "pinyin": "青青子衿{jīn}，悠悠我心。纵我不往，子宁不嗣{sì}音？\n青青子佩，悠悠我思。纵我不往，子宁不来？\n挑{tāo}兮达兮，在城阙{què}兮。一日不见，如三月兮。",
      "translation": "你那青青的衣领，让我心中思念绵绵。纵然我不曾去找你，你难道就不能捎个音信来？你那青青的佩带，让我思念不已。纵然我不曾去找你，你难道就不能来？走来走去，心神不定，在这城楼上。一天不见你，就好像隔了三个月。",
      "analysis": "全诗写女子对恋人的思念。前两章以「青青子衿」「青青子佩」起兴，由衣饰想到人；「纵我不往，子宁不嗣音」写出埋怨中的深情。末章「一日不见，如三月兮」以夸张写相思之苦，成为千古名句。",
