      "dynasty": "唐",
      "author": "杜甫",
      "level": "middle",
      "grade": "八年级下",
      "tag": "忧民",
      "pinyin": "暮投石壕村，有吏夜捉人。老翁逾{yú}墙走，老妇出门看。\n吏呼一何怒！妇啼一何苦！听妇前致词：三男邺{yè}城戍。\n一男附书至，二男新战死。存者且偷生，死者长已矣！\n室中更无人，惟有乳下孙。有孙母未去，出入无完裙。\n老妪{yù}力虽衰，请从吏夜归。急应河阳役，犹得备晨炊。\n夜久语声绝，如闻泣幽咽{yè}。天明登前途，独与老翁别。",
      "translation": "傍晚我投宿在石壕村，夜里有差役来捉人。老翁翻墙逃走，老妇出门去应付。差役吼叫得多么愤怒！老妇啼哭得多么凄苦！我听见老妇上前诉说：三个儿子都在邺城服役。一个儿子捎信回来，说另外两个儿子刚刚战死。活着的暂且偷生，死去的就永远完了！家里再没有别的男人，只有吃奶的小孙子。因为有孙子在，他的母亲没有改嫁，但进进出出连一条完整的裙子都没有。老妇我虽然年老力衰，请让我跟您连夜回去吧。赶快去应付河阳的差役，或许还来得及做早饭。夜深了，说话的声音消失了，好像听到隐隐约约的哭泣声。天亮后我继续赶路，只能和老翁告别。",
      "analysis": "这是杜甫「三吏」之一。全诗以旁观者的角度，客观叙述差役夜捉人的过程。老妇的血泪控诉，层层揭开这个家庭的惨状：三男戍边、二男战死、家徒四壁。诗人不着一字议论，而批判之意自现。结尾「独与老翁别」五字，含蓄而沉痛。",
