      "pinyin": "北国风光，千里冰封，万里雪飘。\n望长城内外，惟余莽莽{mǎng}；大河上下，顿失滔滔。\n山舞银蛇，原驰蜡象，欲与天公试比高。\n须晴日，看红装素裹，分外妖娆{ráo}。\n江山如此多娇，引无数英雄竞折腰。\n惜秦皇汉武，略输文采；唐宗宋祖，稍逊风骚。\n一代天骄，成吉思汗{hán}，只识弯弓射大雕。\n俱往矣，数风流人物，还看今朝。",
