      "pinyin": "十五从军征，八十始得归。道逢乡里人：家中有阿谁？\n遥看是君家，松柏冢{zhǒng}累累。兔从狗窦{dòu}入，雉{zhì}从梁上飞。\n中庭生旅谷，井上生旅葵。舂{chōng}谷持作饭，采葵持作羹{gēng}。\n羹饭一时熟，不知贻{yí}阿谁。出门东向看，泪落沾我衣。",
      "translation": "十五岁就应征从军，八十岁才得以回家。路上遇到同乡的人，问：我家里还有谁？远远看去那就是你家，松柏树下坟墓累累。野兔从狗洞里钻进钻出，野鸡从屋梁上飞起。庭院里长满了野生的谷子，井台上长满了野生的葵菜。舂去谷壳做成饭，采摘葵菜煮成汤。汤饭一会儿就做好了，却不知道该送给谁吃。走出门向东望去，泪水落下沾湿了衣裳。",
