      "grade": "九年级下",
      "tag": "爱国",
      "pinyin": "梅花南北路，风雨湿征衣。\n出岭同谁出？归乡如不归！\n山河千古在，城郭一时非。\n饿死真吾志，梦中行采薇。",
      "translation": "经过梅花岭的南北路上，风雨打湿了征衣。出岭的时候有谁与我同行？回到故乡也如同不归一样！山河千古长存，城郭却一时易主。饿死才是我的志向，梦中也要像伯夷叔齐那样采薇而食。",
      "analysis": "这首诗写于文天祥被俘北解途中。颔联「出岭同谁出？归乡如不归」以反问写孤独与悲愤；颈联「山河千古在，城郭一时非」以永恒的山河对比易主的城郭，沉痛至极；尾联以「饿死真吾志」表明宁死不屈的决心。",
