      "content": "山川之美，古来共谈。高峰入云，清流见底。两岸石壁，五色交辉。\n青林翠竹，四时俱备。晓雾将歇{xiē}，猿鸟乱鸣；夕日欲颓{tuí}，沉鳞{lín}竞跃。\n实是欲界之仙都。自康乐以来，未复有能与{yù}其奇者。",
      "translation": "山川的美丽，自古以来就是人们共同赞叹的。高高的山峰耸入云端，清澈的溪流可以看见水底。两岸的石壁，色彩斑斓，交相辉映。青翠的树林和竹丛，四季都有。清晨的雾气将要消散，猿猴和鸟儿此起彼伏地鸣叫；傍晚的太阳将要落山，潜游在水中的鱼儿争相跳出水面。这里实在是人间的仙境啊。自从谢灵运以来，就再也没有人能够欣赏这种奇丽的景色了。",
      "analysis": "作者以清丽的笔触描绘山川之美：高峰、清流、石壁、青林、翠竹、晓雾、猿鸟、夕日、沉鳞，构成一幅多姿多彩的山水画。最后以「欲界之仙都」赞美，以谢灵运自比，表达了对山川的热爱和自得之情。",
