      "tag": "闲适",
      "summary": "记录月夜与友人散步的情景，抒发旷达乐观的情怀。",
      "content": "元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝{qǐn}，相与步于中庭。\n庭下如积水空明，水中藻{zǎo}荇{xìng}交横，盖竹柏影也。\n何夜无月？何处无竹柏？但少闲人如吾两人者耳。",
      "translation": "元丰六年十月十二日夜晚，我脱下衣服准备睡觉，看到月光照进门里，高兴地起来散步。想到没有可以共同游乐的人，于是就到承天寺去找张怀民。张怀民也还没有睡，我们便一起在庭院中散步。庭院中的月光像积水一样清澈透明，水中的藻类和荇菜交错纵横，原来是竹子和柏树的影子。哪个夜晚没有月光？哪个地方没有竹子和柏树？只是缺少像我们两个这样的闲人罢了。",
      "analysis": "全文仅八十余字，写月夜与友人散步的情景。作者用「积水空明」「藻荇交横」比喻月光和竹柏的影子，想象奇特，意境清幽。结尾「但少闲人如吾两人者耳」既含赏月的自得，也暗含贬谪的悲凉，含蓄隽永。",
