      "id": "w021",
      "title": "诫子书",
      "dynasty": "三国",
      "author": "诸葛亮",
      "tag": "家训",
      "grade": "七年级上",
      "summary": "诸葛亮写给儿子的家书，以「静以修身，俭以养德」告诫修身、立志、惜时。",
      "content": "夫君子之行，静以修身，俭以养德。非淡泊{bó}无以明志，非宁静无以致远。夫学须静也，才须学也，非学无以广才，非志无以成学。淫{yín}慢则不能励{lì}精，险躁{zào}则不能治性。年与时驰{chí}，意与日去，遂成枯落，多不接世，悲守穷庐{lú}，将复何及！",
      "translation": "君子的品行，用宁静来修养身心，用节俭来培养品德。不恬淡寡欲就无法明确志向，不宁静专一就无法达到远大目标。学习必须静心，才干必须学习，不学习就无法增长才干，没有志向就无法成就学业。放纵懈怠就不能振奋精神，轻薄浮躁就不能修养性情。年纪随时光飞驰，意志随岁月消磨，最终枯败零落，大多不能接触世事，只能悲哀地守着穷困的屋舍，那时再后悔又怎么来得及！",
      "analysis": "本文是诸葛亮晚年写给儿子诸葛瞻的家书。开篇提出「静以修身，俭以养德」，接着从立志、学习、惜时三方面告诫：非淡泊无以明志，非宁静无以致远；非学无以广才，非志无以成学；淫慢险躁则不能励精治性。最后以「年与时驰，意与日去」警示珍惜光阴。全文仅八十余字，言简意深，是古代家训的名篇。",
