      "meaning": "「破釜沉舟」比喻下定决心，不留退路，义无反顾。这个故事告诉人们：关键时刻要有果敢的决心和勇气。",
      "points": [
        "「釜」读 fǔ，指锅",
        "成语「破釜沉舟」",
        "主旨：下定决心、义无反顾"
      ]
