      "id": "s012",
      "title": "三顾茅庐",
      "author": "陈寿《三国志》（后世演义有增饰）",
      "dynasty": "东汉",
      "tag": "求贤",
      "summary": "刘备三次到隆中拜访诸葛亮，诚心请他出山。",
      "content": "东汉末年，刘备听说诸葛亮很有才华，就带着关羽、张飞亲自到隆中去请他。第一次去，诸葛亮不在家；第二次去，又没见到。张飞不耐烦了，刘备却坚持再去。第三次去，诸葛亮正在睡觉，刘备就在门外恭恭敬敬地等候，直到他醒来。诸葛亮被刘备的诚心所感动，终于答应出山辅佐刘备。",
      "meaning": "「三顾茅庐」比喻诚心诚意地一再邀请、拜访有才能的人。这个故事赞扬了刘备求贤若渴、礼贤下士的品格。",
      "points": [
        "「顾」意为拜访",
        "「茅庐」指茅草屋",
        "成语「三顾茅庐」",
        "主旨：诚心求贤"
      ]
