      "title": "刻舟求剑",
      "author": "《吕氏春秋·察今》",
      "dynasty": "战国",
      "tag": "寓言",
      "summary": "楚国人在船上刻记号找掉进水里的剑，结果当然找不到。",
      "content": "楚国有个渡江的人，他的剑从船上掉进了水里。他急忙在船舷上刻了一个记号，说：「这是我的剑掉下去的地方。」等船停下来，他就从刻着记号的地方跳进水里去找剑。船已经向前行进了，可是剑并没有动，像这样找剑，不是很糊涂吗？",
