      "tag": "智慧",
      "summary": "曹操用前方有梅林的话激励口渴的士兵，暂时缓解了困境。",
      "content": "有一年夏天，曹操率领军队出征。天气非常炎热，骄阳似火，士兵们走了很久，都口渴难耐，可是附近找不到水源。士兵们一个个口干舌燥，行军的速度越来越慢。曹操看到这种情况，心里很着急。他灵机一动，骑马跑到队伍前面，用马鞭指着前方说：「前面有一大片梅林，结满了又酸又甜的梅子，可以解渴！」士兵们听了，想到梅子的酸味，嘴里不由得流出口水，口渴的感觉暂时缓解了。于是队伍振作精神，继续前进，终于找到了水源。",
      "meaning": "「望梅止渴」比喻用空想来安慰自己，或用来鼓舞士气。这个故事赞扬了曹操的机智应变，也说明在困境中要善于想办法激励人心。",
