      "summary": "宋人嫌禾苗长得慢，亲手拔高，结果禾苗全部枯死。",
      "content": "宋国有个农夫，嫌自己田里的禾苗长得太慢，就一棵一棵地把禾苗往上拔高。他累得筋疲力尽，回到家对家里人说：「今天可把我累坏了！我帮禾苗长高了一大截！」他的儿子急忙跑到田里去看，只见禾苗全都枯萎了。天下不帮助禾苗生长的人很少。以为没有用处而放弃不锄草的，是不锄草的懒汉；违背规律去帮助它生长的，就是拔苗助长的人，不但没有好处，反而害了它。",
      "meaning": "事物发展有自身的规律，违背规律、急于求成，只会把事情办坏。做事要尊重规律、循序渐进。",
