      "summary": "赵括熟读兵书却不会实战，长平之战葬送四十万赵军。",
      "content": "赵括从小学习兵法，谈论起用兵打仗来头头是道，连他的父亲、名将赵奢也难不倒他。但赵奢并不认为他有真本事，对妻子说：「用兵是生死存亡的大事，括儿却说得太轻易。将来赵国不用他则罢，若用他为将，使赵军大败的一定是他。」后来秦国攻打赵国，赵王听信谣言，用赵括代替老将廉颇。赵括一到前线，就照搬兵书上的条文，改变廉颇的部署，轻率出击。秦将白起佯败后退，截断赵军粮道，把赵军团团围住。赵军断粮四十六天，赵括突围时被乱箭射死，四十多万赵军全部覆没。",
