      "summary": "以叠字开篇，写尽国破家亡后的凄凉愁苦。",
      "pinyin": "寻寻觅觅，冷冷清清，凄凄惨惨戚戚{qī}。\n乍暖还寒时候，最难将息。\n三杯两盏淡酒，怎敌他、晚来风急！\n雁过也，正伤心，却是旧时相识。\n满地黄花堆积。憔悴损，如今有谁堪摘？\n守着窗儿，独自怎生得黑！\n梧桐更兼细雨，到黄昏、点点滴滴。\n这次第，怎一个愁字了得！",
