      "grade": "拓展",
      "summary": "南唐后主李煜的绝命词，写尽亡国之痛。",
      "pinyin": "春花秋月何时了？往事知多少。\n小楼昨夜又东风，故国不堪回首月明中。\n雕栏玉砌{qì}应犹在，只是朱颜改。\n问君能有几多愁？恰似一江春水向东流。",
      "translation": "春花秋月什么时候才能了结？往事又知道多少。小楼昨夜又吹起了东风，在皎洁的月光下，不忍回首故国的情景。雕花的栏杆、玉石砌成的台阶应该还在，只是宫女们的容颜已经改变了。要问我能有多少愁？就像那一江春水滚滚向东流去。",
