      "author": "柳永",
      "tag": "名篇",
      "grade": "拓展",
      "summary": "写离别之情，情景交融，是婉约词的代表作。",
      "pinyin": "寒蝉凄切，对长亭晚，骤雨初歇。\n都门帐饮无绪，留恋处，兰舟催发。\n执手相看泪眼，竟无语凝噎{yē}。\n念去去，千里烟波，暮霭{ǎi}沉沉楚天阔。\n多情自古伤离别，更那堪，冷落清秋节！\n今宵酒醒何处？杨柳岸，晓风残月。\n此去经年，应是良辰好景虚设。\n便纵有千种风情，更与何人说？",
      "translation": "寒蝉叫得凄切，面对着长亭，已是傍晚，一阵急雨刚刚停歇。在京城门外设帐饯别，却没有心情饮酒；正在留恋不舍时，船夫催促着要开船。握着双手相互凝视，泪眼朦胧，竟哽咽得说不出话来。想到此去一程又一程，千里烟波浩渺，暮霭沉沉，楚地的天空辽阔无边。自古以来多情的人就为离别而伤感，更何况在这冷落凄清的秋天！今晚酒醒时身在何处？恐怕是在杨柳岸边，面对着晓风和残月。这一去多年，良辰美景也形同虚设。即使有千种风情，又能对谁诉说呢？",
