      "pinyin": "千古江山，英雄无觅，孙仲谋处。舞榭{xiè}歌台，风流总被，雨打风吹去。斜阳草树，寻常巷陌{mò}，人道寄奴曾住。想当年，金戈铁马，气吞万里如虎。\n元嘉{jiā}草草，封狼居胥{xū}，赢得仓皇北顾。四十三年，望中犹记，烽火扬州路。可堪回首，佛{bì}狸{lí}祠{cí}下，一片神鸦社鼓。凭谁问：廉颇老矣，尚能饭否？",
      "translation": "千古江山依旧，却无处寻找孙权那样的英雄。当年的舞榭歌台，风流韵事，都被雨打风吹去了。夕阳照在草树上，普通的街巷，人们说刘裕曾在这里住过。想当年，他金戈铁马，气吞万里如猛虎。\n元嘉年间草率北伐，想建立封狼居胥的功业，结果只落得仓皇北望。四十三年过去，望中还记得扬州路上的烽火。怎能回首，佛狸祠下，一片神鸦社鼓。靠谁去问：廉颇老了，还能吃饭吗？",
      "analysis": "这首词写于辛弃疾任镇江知府时。上片由京口形胜联想到孙权、刘裕，赞其英雄业绩，暗讽南宋朝廷的怯懦；下片借刘义隆草率北伐失败的教训，警告当权者不可轻举妄动，又以「佛狸祠下」写沦陷区百姓安于异族统治，最后以廉颇自比，抒发不被重用、报国无门的悲愤。全词用典密集而贴切，沉郁苍凉。",
