      "summary": "游武侯祠怀诸葛亮，赞其功业，叹其壮志未酬。",
      "pinyin": "丞相祠堂何处寻？锦官城外柏{bǎi}森森。\n映阶碧草自春色，隔叶黄鹂{lí}空好音。\n三顾频烦天下计，两朝开济老臣心。\n出师未捷身先死，长使英雄泪满襟{jīn}。",
      "translation": "诸葛丞相的祠堂到哪里去寻找？在锦官城外柏树茂密的地方。碧草映着台阶，空自呈现一片春色；黄鹂隔着树叶，徒然发出美妙的鸣声。三顾茅庐，频频请教天下大计；辅佐两朝，开创基业，是老臣的一片忠心。出师还没有取得胜利就身先死去，长久地使英雄们泪满衣襟。",
      "analysis": "这首诗是杜甫寓居成都时游武侯祠所作。首联设问点明地点，颔联写景，「自」「空」二字写出祠庙寂寥、英雄已逝的怅惘；颈联概括诸葛亮三顾出山、辅佐两朝的功业与忠心；尾联「出师未捷身先死，长使英雄泪满襟」抒发壮志未酬的悲慨。全诗沉郁顿挫，是咏史怀古的名篇。",
