        "「煴火」读 yūn huǒ，微火",
        "「啮雪」读 niè xuě，咬雪",
        "「羝」读 dī，公羊",
        "「节旄」读 jié máo，汉节上的旄牛尾装饰",
        "「檠弓弩」的「檠」读 qíng，矫正",
        "「汤镬」读 tāng huò，古代酷刑，把人投入沸水锅中",
