        "「唐雎」读 táng jū，人名",
        "「错意」同「措意」，在意、放在心上",
        "「怫然」读 fú rán，愤怒的样子",
        "「徒跣」读 tú xiǎn，光着脚",
        "「以头抢地」的「抢」读 qiāng，撞",
        "「韩傀」读 hán kuǐ，韩国相国",
        "「休祲」读 xiū jìn，吉凶的征兆",
        "「缟素」读 gǎo sù，白色丧服",
        "「色挠」读 sè náo，脸色屈服",
        "名句：若士必怒，伏尸二人，流血五步，天下缟素",
        "主旨：赞颂唐雎不畏强暴、维护国家尊严的精神"
